		parentTree:            o.parentTree,
		repoDir:               o.repoDir,
		attributionBaseCommit: attrBase,
		parentCommitHash:      o.parentCommitHash,
		headCommitHash:        o.headCommitHash,
		allAgentFiles:         o.allAgentFiles,
	})

