	for _, ag := range addedAgents {
		if _, err := setupAgentHooks(ctx, ag, opts.LocalDev, opts.ForceHooks); err != nil {
			errs = append(errs, fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err))

